-- PT116-S3-Q14. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT116-S3-Q14$batch10$ AND q.stimulus=$batch10$Social critic: The operas composed by Bizet and Verdi are nineteenth-century European creations, reflecting the attitudes and values in France and Italy at the end of that century. Several recent studies impugn these operas on the grounds that they reinforce in our society many stereotypes about women. But only a small minority of contemporary North Americans, namely opera lovers, have had any significant exposure to these works.$batch10$ AND q.prompt=$batch10$Which one of the following most accurately expresses the conclusion that the social critic's argument, as it is stated above, is structured to establish?$batch10$ AND q.correct_choice=$batch10$C$batch10$) THEN RAISE EXCEPTION 'Question changed: PT116-S3-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT116-S3-Q14$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT116-S3-Q14'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT116-S3-Q14$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Opposing Point$batch10$, $batch10$Recent studies say the operas of Bizet and Verdi reinforce stereotypes about women in our society.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$Only a small minority of North Americans, opera lovers, have had any significant exposure to these operas.$batch10$), (2, $batch10$Conclusion$batch10$, $batch10$(Unstated) These operas have not significantly contributed to stereotypes about women in contemporary North America.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$The stem asks for the conclusion the argument is "structured to establish," which hints that it isn't stated outright. The critic answers the studies with "But only a small minority" have seen these works. The point being made is that the operas couldn't be shaping our stereotypes much.$batch10$), (4, $batch10$Goal$batch10$, $batch10$The operas have not significantly shaped stereotypes of women in North America today.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT116-S3-Q14$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This is roughly what the studies claim. The critic is arguing against it.$batch10$), ($batch10$B$batch10$, $batch10$The critic never compares nineteenth-century images of women with current ones.$batch10$), ($batch10$C$batch10$, $batch10$The critic's evidence, that few North Americans have seen the operas, is aimed at showing the operas haven't significantly reinforced stereotypes here. That's the unstated conclusion.$batch10$), ($batch10$D$batch10$, $batch10$The critic talks only about these operas, not opera as a whole as a force on social attitudes.$batch10$), ($batch10$E$batch10$, $batch10$The critic needs only that limited exposure means limited influence. "Cannot be influenced" by anything not directly seen goes much further. It's closer to an assumption than to the conclusion.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT116-S3-Q14$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
